    { const char * tb_v380 = "// задачи и планировщик, страницы памяти, несколько ядер процессора (ACPI, APIC).\n"; *(const char * *)tb_grow(v_lines) = tb_v380; }
    { const char * tb_v381 = "// Компилятор вставляет этот файл в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v381; }
    { const char * tb_v382 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v382; }
    { const char * tb_v383 = "// ---------- режим без ОС (tb bare): своя маленькая библиотека вместо libc ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v383; }
    { const char * tb_v384 = "// Программа сама себе ОС: загружается через multiboot (QEMU, GRUB), пишет на экран\n"; *(const char * *)tb_grow(v_lines) = tb_v384; }
    { const char * tb_v385 = "// (текстовый режим VGA) и в последовательный порт COM1, память берёт из своего запаса.\n"; *(const char * *)tb_grow(v_lines) = tb_v385; }
    { const char * tb_v386 = "// Есть прерывания, таймер, клавиатура, задачи (background) и страницы памяти; файлов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v386; }
    { const char * tb_v387 = "#include <stddef.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v387; }
