    { const char * tb_v410 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v410; }
    { const char * tb_v411 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v411; }
    { const char * tb_v412 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v412; }
    { const char * tb_v413 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v413; }
    { const char * tb_v414 = "    struct tb_cpu_s *self;\n"; *(const char * *)tb_grow(v_lines) = tb_v414; }
    { const char * tb_v415 = "    int id, apic, run, slice, depth, prev;   // run: номер задачи (-1 — пустой ход); depth: вложенность «общего замка»; prev: задача, которую отпустить после смены стека\n"; *(const char * *)tb_grow(v_lines) = tb_v415; }
    { const char * tb_v416 = "    uint64_t *idle_frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v416; }
