    { const char * tb_v433 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v433; }
    { const char * tb_v434 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v434; }
    { const char * tb_v435 = "TB_INL void tb_irq_restore(uint64_t f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v435; }
    { const char * tb_v436 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v436; }
    { const char * tb_v437 = "    if (--c->depth == 0) __atomic_store_n(&tb_bkl, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v437; }
    { const char * tb_v438 = "    __asm__ volatile(\"pushq %0\\npopfq\" : : \"r\"(f) : \"memory\", \"cc\");\n"; *(const char * *)tb_grow(v_lines) = tb_v438; }
    { const char * tb_v439 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v439; }
    { const char * tb_v440 = "// отдать общий замок целиком (задача уходит навсегда — падает или кончилась)\n"; *(const char * *)tb_grow(v_lines) = tb_v440; }
    { const char * tb_v441 = "TB_INL void tb_bkl_drop(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v441; }
    { const char * tb_v442 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v442; }
