    { const char * tb_v532 = "TB_API void tb_vga_font(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v532; }
    { const char * tb_v533 = "    tb_outw(0x3C4, 0x0402); tb_outw(0x3C4, 0x0704);   // пишем в слой шрифта\n"; *(const char * *)tb_grow(v_lines) = tb_v533; }
    { const char * tb_v534 = "    tb_outw(0x3CE, 0x0204); tb_outw(0x3CE, 0x0005); tb_outw(0x3CE, 0x0406);\n"; *(const char * *)tb_grow(v_lines) = tb_v534; }
    { const char * tb_v535 = "    volatile unsigned char *font = (volatile unsigned char *)0xA0000;\n"; *(const char * *)tb_grow(v_lines) = tb_v535; }
    { const char * tb_v536 = "    for (int i = 0; i < 66; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v536; }
    { const char * tb_v537 = "        for (int y = 0; y < 16; y++) font[(128 + i) * 32 + y] = tb_cyr_font[i][y];\n"; *(const char * *)tb_grow(v_lines) = tb_v537; }
    { const char * tb_v538 = "    tb_outw(0x3C4, 0x0302); tb_outw(0x3C4, 0x0304);   // обратно в текстовый режим\n"; *(const char * *)tb_grow(v_lines) = tb_v538; }
    { const char * tb_v539 = "    tb_outw(0x3CE, 0x0004); tb_outw(0x3CE, 0x1005); tb_outw(0x3CE, 0x0E06);\n"; *(const char * *)tb_grow(v_lines) = tb_v539; }
    { const char * tb_v540 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v540; }
    { const char * tb_v541 = "TB_API unsigned char tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v541; }
    { const char * tb_v542 = "TB_API void tb_putc(char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v542; }
    { const char * tb_v543 = "    unsigned char ch = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v543; }
    { const char * tb_v544 = "    while ((tb_inb(0x3F8 + 5) & 0x20) == 0) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v544; }
    { const char * tb_v545 = "    tb_outb(0x3F8, ch);   // в порт — как есть (UTF-8)\n"; *(const char * *)tb_grow(v_lines) = tb_v545; }
    { const char * tb_v546 = "    if (ch < 0x80) { tb_utf_lead = 0; tb_vga_put(ch); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v546; }
    { const char * tb_v547 = "    if (ch >= 0xC0) { tb_utf_lead = ch; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v547; }
    { const char * tb_v548 = "    // второй байт: А..я = U+0410..U+044F, Ё = U+0401, ё = U+0451\n"; *(const char * *)tb_grow(v_lines) = tb_v548; }
    { const char * tb_v549 = "    unsigned cp = ((unsigned)(tb_utf_lead & 0x1F) << 6) | (ch & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v549; }
    { const char * tb_v550 = "    if (tb_utf_lead == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v550; }
    { const char * tb_v551 = "    tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v551; }
    { const char * tb_v552 = "    if (cp >= 0x410 && cp <= 0x44F) tb_vga_put((unsigned char)(128 + cp - 0x410));\n"; *(const char * *)tb_grow(v_lines) = tb_v552; }
    { const char * tb_v553 = "    else if (cp == 0x401) tb_vga_put(128 + 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v553; }
    { const char * tb_v554 = "    else if (cp == 0x451) tb_vga_put(128 + 65);\n"; *(const char * *)tb_grow(v_lines) = tb_v554; }
    { const char * tb_v555 = "    else tb_vga_put('?');\n"; *(const char * *)tb_grow(v_lines) = tb_v555; }
    { const char * tb_v556 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v556; }
    { const char * tb_v557 = "// строка не рвётся: пока задача не дописала свою строку до '\\n', другие ждут (недолго —\n"; *(const char * *)tb_grow(v_lines) = tb_v557; }
    { const char * tb_v558 = "// если задача так и не допишет, через ~20 мс пишут всё равно)\n"; *(const char * *)tb_grow(v_lines) = tb_v558; }
    { const char * tb_v559 = "TB_API volatile long long tb_line_owner = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v559; }
    { const char * tb_v560 = "TB_API long long tb_out_me(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v560; }
    { const char * tb_v561 = "TB_API int fputs(const char *s, FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v561; }
    { const char * tb_v562 = "    if (!*s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v562; }
    { const char * tb_v563 = "    long long me = tb_out_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v563; }
    { const char * tb_v564 = "    uint64_t fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v564; }
    { const char * tb_v565 = "    for (long spins = 0;; spins++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v565; }
    { const char * tb_v566 = "        fl = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v566; }
    { const char * tb_v567 = "        long long o = tb_line_owner;\n"; *(const char * *)tb_grow(v_lines) = tb_v567; }
    { const char * tb_v568 = "        if (o == 0 || o == me || me < 0 || spins > 4000000) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v568; }
    { const char * tb_v569 = "        tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v569; }
    { const char * tb_v570 = "        __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v570; }
    { const char * tb_v571 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v571; }
    { const char * tb_v572 = "    unsigned char was = tb_vcolor;\n"; *(const char * *)tb_grow(v_lines) = tb_v572; }
    { const char * tb_v573 = "    if (f == stderr) tb_vcolor = 0x0C;   // ошибки — красным\n"; *(const char * *)tb_grow(v_lines) = tb_v573; }
    { const char * tb_v574 = "    char last = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v574; }
    { const char * tb_v575 = "    while (*s) { last = *s; tb_putc(*s++); }\n"; *(const char * *)tb_grow(v_lines) = tb_v575; }
    { const char * tb_v576 = "    tb_vcolor = was;\n"; *(const char * *)tb_grow(v_lines) = tb_v576; }
    { const char * tb_v577 = "    if (me >= 0) tb_line_owner = last == '\\n' ? 0 : me;\n"; *(const char * *)tb_grow(v_lines) = tb_v577; }
    { const char * tb_v578 = "    tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v578; }
    { const char * tb_v579 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v579; }
    { const char * tb_v580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v580; }
    { const char * tb_v581 = "TB_API int fflush(FILE *f) { (void)f; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v581; }
    { const char * tb_v582 = "TB_API int isatty(int fd) { (void)fd; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v582; }
    { const char * tb_v583 = "TB_API char *getenv(const char *n) { (void)n; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v583; }
    { const char * tb_v584 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v584; }
    { const char * tb_v585 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v585; }
    { const char * tb_v586 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v586; }
    { const char * tb_v587 = "    tb_outb(0xF4, (unsigned char)code);\n"; *(const char * *)tb_grow(v_lines) = tb_v587; }
    { const char * tb_v588 = "    for (;;) __asm__ volatile(\"cli; hlt\");\n"; *(const char * *)tb_grow(v_lines) = tb_v588; }
    { const char * tb_v589 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v589; }
    { const char * tb_v590 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v590; }
    { const char * tb_v591 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v591; }
    { const char * tb_v592 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v592; }
    { const char * tb_v593 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v593; }
    { const char * tb_v594 = "TB_API unsigned char tb_heap[TB_HEAP] __attribute__((aligned(16), section(\".tbheap\")));\n"; *(const char * *)tb_grow(v_lines) = tb_v594; }
    { const char * tb_v595 = "TB_API size_t tb_heap_top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v595; }
    { const char * tb_v596 = "TB_API void *tb_bins[32];\n"; *(const char * *)tb_grow(v_lines) = tb_v596; }
    { const char * tb_v597 = "// заголовок куска: размер (номер 4..31) + метка «это начало куска» — так по адресу видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v597; }
    { const char * tb_v598 = "// наш ли это кусок (для передачи владения), и хозяин (клетка) рядом\n"; *(const char * *)tb_grow(v_lines) = tb_v598; }
    { const char * tb_v599 = "#define TB_HMAGIC 0x0B1A0C0000000000ull\n"; *(const char * *)tb_grow(v_lines) = tb_v599; }
    { const char * tb_v600 = "#define TB_TAG_FREE (~0ull)\n"; *(const char * *)tb_grow(v_lines) = tb_v600; }
    { const char * tb_v601 = "// запас памяти (как зона Service в старой Омниум): последние 8 МБ кучи берут только ядро,\n"; *(const char * *)tb_grow(v_lines) = tb_v601; }
