    { const char * tb_v912 = "        const unsigned char *p = (const unsigned char *)base + mid * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "        int c = cmp(key, p);\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
