    { const char * tb_v942 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "TB_API uint64_t tb_gdt[3 + 2 * TB_NCPU] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL};\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
