    { const char * tb_v952 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
    { const char * tb_v953 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v953; }
    { const char * tb_v954 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v954; }
    { const char * tb_v955 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
    { const char * tb_v957 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v957; }
    { const char * tb_v958 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
