    { const char * tb_v3666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
