    { const char * tb_v3683 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
    { const char * tb_v3688 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
    { const char * tb_v3708 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3708; }
    { const char * tb_v3709 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3709; }
    { const char * tb_v3710 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3710; }
    { const char * tb_v3711 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3711; }
