    { const char * tb_v3879 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3879; }
    { const char * tb_v3880 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3880; }
    { const char * tb_v3881 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3881; }
    { const char * tb_v3882 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3882; }
    { const char * tb_v3883 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v3883; }
    { const char * tb_v3884 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3884; }
    { const char * tb_v3885 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v3885; }
    { const char * tb_v3886 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3886; }
    { const char * tb_v3887 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3887; }
    { const char * tb_v3888 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3888; }
    { const char * tb_v3889 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3889; }
