    { const char * tb_v4004 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v4004; }
    { const char * tb_v4005 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4005; }
