    { const char * tb_v4020 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4020; }
    { const char * tb_v4021 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v4021; }
    { const char * tb_v4022 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v4022; }
    { const char * tb_v4023 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v4023; }
