    { const char * tb_v4537 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v4537; }
    { const char * tb_v4538 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4538; }
    { const char * tb_v4539 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v4539; }
    { const char * tb_v4540 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4540; }
    { const char * tb_v4541 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4541; }
    { const char * tb_v4542 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4542; }
