    { const char * tb_v4546 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4546; }
    { const char * tb_v4547 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4547; }
    { const char * tb_v4548 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4548; }
    { const char * tb_v4549 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v4549; }
