    { const char * tb_v5218 = "// любой формат: по первым байтам\n"; *(const char * *)tb_grow(v_lines) = tb_v5218; }
    { const char * tb_v5219 = "TB_API uint32_t *tb_image_decode(const unsigned char *d, size_t n, int *pw, int *ph, const char **why) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5219; }
    { const char * tb_v5220 = "    if (n >= 8 && d[0] == 137 && d[1] == 'P') return tb_png(d, n, pw, ph, why);\n"; *(const char * *)tb_grow(v_lines) = tb_v5220; }
