    { const char * tb_v5250 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5250; }
    { const char * tb_v5251 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5251; }
    { const char * tb_v5252 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5252; }
    { const char * tb_v5253 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5253; }
    { const char * tb_v5254 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5254; }
    { const char * tb_v5255 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5255; }
    { const char * tb_v5256 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5256; }
    { const char * tb_v5257 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5257; }
    { const char * tb_v5258 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v5258; }
