    { const char * tb_v5358 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5358; }
    { const char * tb_v5359 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v5359; }
    { const char * tb_v5360 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5360; }
