    { const char * tb_v5612 = "    for (int j = 0; j < h; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5612; }
    { const char * tb_v5613 = "        float sum = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5613; }
    { const char * tb_v5614 = "        const float *row = acc + (size_t)j * (w + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5614; }
