    { const char * tb_v5755 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5755; }
    { const char * tb_v5756 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5756; }
    { const char * tb_v5757 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5757; }
