    { const char * tb_v5760 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v5760; }
    { const char * tb_v5761 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5761; }
    { const char * tb_v5762 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5762; }
    { const char * tb_v5763 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5763; }
    { const char * tb_v5764 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5764; }
    { const char * tb_v5765 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5765; }
    { const char * tb_v5766 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5766; }
    { const char * tb_v5767 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5767; }
    { const char * tb_v5768 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v5768; }
    { const char * tb_v5769 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5769; }
    { const char * tb_v5770 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v5770; }
    { const char * tb_v5771 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5771; }
    { const char * tb_v5772 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5772; }
    { const char * tb_v5773 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5773; }
    { const char * tb_v5774 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5774; }
    { const char * tb_v5775 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5775; }
    { const char * tb_v5776 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5776; }
    { const char * tb_v5777 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5777; }
    { const char * tb_v5778 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5778; }
    { const char * tb_v5779 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5779; }
    { const char * tb_v5780 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5780; }
    { const char * tb_v5781 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5781; }
    { const char * tb_v5782 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5782; }
    { const char * tb_v5783 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5783; }
    { const char * tb_v5784 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5784; }
    { const char * tb_v5785 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5785; }
    { const char * tb_v5786 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5786; }
    { const char * tb_v5787 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5787; }
    { const char * tb_v5788 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5788; }
    { const char * tb_v5789 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5789; }
    { const char * tb_v5790 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5790; }
    { const char * tb_v5791 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5791; }
    { const char * tb_v5792 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5792; }
    { const char * tb_v5793 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5793; }
    { const char * tb_v5794 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5794; }
    { const char * tb_v5795 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5795; }
    { const char * tb_v5796 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5796; }
    { const char * tb_v5797 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5797; }
    { const char * tb_v5798 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v5798; }
    { const char * tb_v5799 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5799; }
    { const char * tb_v5800 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5800; }
    { const char * tb_v5801 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5801; }
    { const char * tb_v5802 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5802; }
    { const char * tb_v5803 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5803; }
    { const char * tb_v5804 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5804; }
    { const char * tb_v5805 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5805; }
    { const char * tb_v5806 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5806; }
    { const char * tb_v5807 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5807; }
    { const char * tb_v5808 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v5808; }
    { const char * tb_v5809 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5809; }
