    { const char * tb_v5827 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v5827; }
    { const char * tb_v5828 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5828; }
    { const char * tb_v5829 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5829; }
    { const char * tb_v5830 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v5830; }
    { const char * tb_v5831 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v5831; }
    { const char * tb_v5832 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5832; }
    { const char * tb_v5833 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v5833; }
    { const char * tb_v5834 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5834; }
    { const char * tb_v5835 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5835; }
    { const char * tb_v5836 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v5836; }
    { const char * tb_v5837 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5837; }
    { const char * tb_v5838 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5838; }
    { const char * tb_v5839 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5839; }
    { const char * tb_v5840 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v5840; }
    { const char * tb_v5841 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v5841; }
    { const char * tb_v5842 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v5842; }
    { const char * tb_v5843 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v5843; }
    { const char * tb_v5844 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v5844; }
    { const char * tb_v5845 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5845; }
    { const char * tb_v5846 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5846; }
    { const char * tb_v5847 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5847; }
    { const char * tb_v5848 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5848; }
    { const char * tb_v5849 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5849; }
