    { const char * tb_v5855 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v5855; }
    { const char * tb_v5856 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5856; }
