    { const char * tb_v5861 = "// ---------- Vulkan (Linux и Windows) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5861; }
    { const char * tb_v5862 = "// Свои описания Vulkan (только то, что нужно): программе не нужны заголовки Vulkan,\n"; *(const char * *)tb_grow(v_lines) = tb_v5862; }
