    { const char * tb_v7785 = "// Экран и мышь Омниума (tb bare + рисование): видеокарта QEMU/Bochs, мышь PS/2 и vmmouse.\n"; *(const char * *)tb_grow(v_lines) = tb_v7785; }
    { const char * tb_v7786 = "// Вставляется в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v7786; }
    { const char * tb_v7787 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7787; }
    { const char * tb_v7788 = "// ---------- экран и мышь в ядре (tb bare) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7788; }
    { const char * tb_v7789 = "// Экран: видеокарта Bochs/QEMU (BGA, «-vga std»): режим w×h, 32 бита на точку, буфер кадра в памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v7789; }
    { const char * tb_v7790 = "// Где буфер — говорит шина PCI (BAR0). Кадр рисуется в tb_px, на экран копируется целиком.\n"; *(const char * *)tb_grow(v_lines) = tb_v7790; }
    { const char * tb_v7791 = "// Мышь PS/2 (прерывание 12), клавиатура — та же, что для read_key.\n"; *(const char * *)tb_grow(v_lines) = tb_v7791; }
    { const char * tb_v7792 = "TB_API volatile uint32_t *tb_lfb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7792; }
    { const char * tb_v7793 = "TB_API int tb_bcur = 0;          // курсор: 0 стрелка ... 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v7793; }
    { const char * tb_v7794 = "TB_API char *tb_bclip = 0;       // буфер обмена — просто текст в памяти ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v7794; }
    { const char * tb_v7795 = "TB_API unsigned tb_pci_r(int bus, int dev, int fn, int off) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7795; }
    { const char * tb_v7796 = "    tb_outl(0xCF8, 0x80000000u | (unsigned)bus << 16 | (unsigned)dev << 11 | (unsigned)fn << 8 | (unsigned)(off & 0xFC));\n"; *(const char * *)tb_grow(v_lines) = tb_v7796; }
    { const char * tb_v7797 = "    return tb_inl(0xCFC);\n"; *(const char * *)tb_grow(v_lines) = tb_v7797; }
    { const char * tb_v7798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7798; }
    { const char * tb_v7799 = "TB_API uint64_t tb_bga_find(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7799; }
    { const char * tb_v7800 = "    for (int bus = 0; bus < 8; bus++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7800; }
    { const char * tb_v7801 = "        for (int dev = 0; dev < 32; dev++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7801; }
    { const char * tb_v7802 = "            unsigned id = tb_pci_r(bus, dev, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7802; }
    { const char * tb_v7803 = "            if (id == 0x11111234u || id == 0xBEEF80EEu) return tb_pci_r(bus, dev, 0, 0x10) & ~0xFu;\n"; *(const char * *)tb_grow(v_lines) = tb_v7803; }
    { const char * tb_v7804 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7804; }
    { const char * tb_v7805 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7805; }
    { const char * tb_v7806 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7806; }
    { const char * tb_v7807 = "TB_API void tb_bga_w(unsigned short i, unsigned short v) { tb_outw(0x1CE, i); tb_outw(0x1CF, v); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7807; }
    { const char * tb_v7808 = "TB_API unsigned short tb_bga_r(unsigned short i) { tb_outw(0x1CE, i); return tb_inw(0x1CF); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7808; }
    { const char * tb_v7809 = "// окно устройства в страницы (по 2 МБ, писать можно, без кэша чтения)\n"; *(const char * *)tb_grow(v_lines) = tb_v7809; }
    { const char * tb_v7810 = "TB_API void tb_map_dev(uint64_t a, uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7810; }
    { const char * tb_v7811 = "    for (uint64_t p = a & ~0x1FFFFFull; p < a + n; p += 0x200000ull) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7811; }
    { const char * tb_v7812 = "        if (p >= (64ull << 30)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7812; }
