    { const char * tb_v7814 = "        tb_pdir[p >> 30][(p >> 21) & 511] = p | 0x83 | 0x8;   // 0x8: запись сквозная — кадр сразу виден\n"; *(const char * *)tb_grow(v_lines) = tb_v7814; }
    { const char * tb_v7815 = "        __asm__ volatile(\"invlpg (%0)\" : : \"r\"(p) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7815; }
    { const char * tb_v7816 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7816; }
    { const char * tb_v7817 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7817; }
    { const char * tb_v7818 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v7818; }
    { const char * tb_v7819 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7819; }
    { const char * tb_v7820 = "TB_API int tb_sc_key(unsigned char sc, int ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7820; }
    { const char * tb_v7821 = "    if (ext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7821; }
    { const char * tb_v7822 = "        switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7822; }
    { const char * tb_v7823 = "        case 0x48: return TB_K_UP; case 0x50: return TB_K_DOWN; case 0x4D: return TB_K_RIGHT; case 0x4B: return TB_K_LEFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7823; }
    { const char * tb_v7824 = "        case 0x53: return TB_K_DEL; case 0x47: return TB_K_HOME; case 0x4F: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v7824; }
    { const char * tb_v7825 = "        case 0x49: return TB_K_PGUP; case 0x51: return TB_K_PGDN; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7825; }
    { const char * tb_v7826 = "        case 0x1C: return TB_K_ENTER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7826; }
    { const char * tb_v7827 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7827; }
    { const char * tb_v7828 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7828; }
    { const char * tb_v7829 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7829; }
    { const char * tb_v7830 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7830; }
    { const char * tb_v7831 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v7831; }
    { const char * tb_v7832 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v7832; }
    { const char * tb_v7833 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v7833; }
    { const char * tb_v7834 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7834; }
    { const char * tb_v7835 = "    if (sc >= 0x3B && sc <= 0x44) return TB_K_F1 + (sc - 0x3B);\n"; *(const char * *)tb_grow(v_lines) = tb_v7835; }
    { const char * tb_v7836 = "    if (sc < 58) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7836; }
    { const char * tb_v7837 = "        int ch = (unsigned char)tb_kmap[0][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v7837; }
    { const char * tb_v7838 = "        if (ch >= 'a' && ch <= 'z') return ch - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v7838; }
    { const char * tb_v7839 = "        if (ch >= '0' && ch <= '9') return ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7839; }
    { const char * tb_v7840 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7840; }
    { const char * tb_v7841 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7841; }
    { const char * tb_v7842 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7842; }
    { const char * tb_v7843 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7843; }
    { const char * tb_v7844 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7844; }
    { const char * tb_v7845 = "    int up = sc & 0x80, ext = tb_kext;\n"; *(const char * *)tb_grow(v_lines) = tb_v7845; }
    { const char * tb_v7846 = "    tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7846; }
    { const char * tb_v7847 = "    sc &= 0x7F;\n"; *(const char * *)tb_grow(v_lines) = tb_v7847; }
    { const char * tb_v7848 = "    int k = tb_sc_key(sc, ext);\n"; *(const char * *)tb_grow(v_lines) = tb_v7848; }
    { const char * tb_v7849 = "    if (k) { tb_keys[k] = !up; if (!up) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7849; }
    { const char * tb_v7850 = "    if (!up && !ext && sc < 58 && !tb_keys[TB_K_CTRL]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7850; }
    { const char * tb_v7851 = "        char ch = tb_kmap[tb_keys[TB_K_SHIFT] ? 1 : 0][sc];\n"; *(const char * *)tb_grow(v_lines) = tb_v7851; }
    { const char * tb_v7852 = "        if ((unsigned char)ch >= 32) tb_type_cp((unsigned char)ch);\n"; *(const char * *)tb_grow(v_lines) = tb_v7852; }
    { const char * tb_v7853 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7853; }
    { const char * tb_v7854 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7854; }
    { const char * tb_v7855 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v7855; }
    { const char * tb_v7856 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7856; }
    { const char * tb_v7857 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7857; }
    { const char * tb_v7858 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v7858; }
    { const char * tb_v7859 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7859; }
    { const char * tb_v7860 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v7860; }
    { const char * tb_v7861 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7861; }
    { const char * tb_v7862 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7862; }
    { const char * tb_v7863 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7863; }
    { const char * tb_v7864 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7864; }
    { const char * tb_v7865 = "    tb_ps2_wait_in(); tb_outb(0x60, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7865; }
    { const char * tb_v7866 = "    return tb_ps2_read();   // 0xFA — принято\n"; *(const char * *)tb_grow(v_lines) = tb_v7866; }
    { const char * tb_v7867 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7867; }
    { const char * tb_v7868 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v7868; }
    { const char * tb_v7869 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v7869; }
    { const char * tb_v7870 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7870; }
    { const char * tb_v7871 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7871; }
    { const char * tb_v7872 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v7872; }
    { const char * tb_v7873 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7873; }
    { const char * tb_v7874 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7874; }
    { const char * tb_v7875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7875; }
    { const char * tb_v7876 = "TB_API void tb_vmm_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7876; }
    { const char * tb_v7877 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7877; }
    { const char * tb_v7878 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v7878; }
    { const char * tb_v7879 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7879; }
    { const char * tb_v7880 = "    tb_vmm_call(41, 0x45414552u, r);                     // включить\n"; *(const char * *)tb_grow(v_lines) = tb_v7880; }
    { const char * tb_v7881 = "    tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7881; }
    { const char * tb_v7882 = "    if (r[0] == 0xFFFF0000u || (r[0] & 0xFFFF) == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7882; }
    { const char * tb_v7883 = "    tb_vmm_call(39, 1, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7883; }
    { const char * tb_v7884 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7884; }
    { const char * tb_v7885 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v7885; }
    { const char * tb_v7886 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7886; }
    { const char * tb_v7887 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7887; }
    { const char * tb_v7888 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7888; }
    { const char * tb_v7889 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7889; }
    { const char * tb_v7890 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7890; }
    { const char * tb_v7891 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7891; }
    { const char * tb_v7892 = "        if (r[0] == 0xFFFF0000u) { tb_vmm = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7892; }
    { const char * tb_v7893 = "        if ((r[0] & 0xFFFF) < 4) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7893; }
    { const char * tb_v7894 = "        tb_vmm_call(39, 4, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v7894; }
    { const char * tb_v7895 = "        tb_mx = (int)((uint64_t)r[1] * (uint64_t)tb_gw / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v7895; }
    { const char * tb_v7896 = "        tb_my = (int)((uint64_t)r[2] * (uint64_t)tb_gh / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v7896; }
    { const char * tb_v7897 = "        int down = (r[0] & 0x20) != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7897; }
    { const char * tb_v7898 = "        if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
    { const char * tb_v7899 = "        tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v7899; }
    { const char * tb_v7900 = "        int w = (int)(signed char)(r[3] & 0xFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v7900; }
    { const char * tb_v7901 = "        if (w) tb_wheel_add(-w);\n"; *(const char * *)tb_grow(v_lines) = tb_v7901; }
    { const char * tb_v7902 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7902; }
    { const char * tb_v7903 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7903; }
    { const char * tb_v7904 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7904; }
    { const char * tb_v7905 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7905; }
    { const char * tb_v7906 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7906; }
    { const char * tb_v7907 = "    unsigned char b = tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v7907; }
    { const char * tb_v7908 = "    if (!(st & 0x20)) { tb_key_byte(b); return; }   // байт клавиатуры пришёл сюда\n"; *(const char * *)tb_grow(v_lines) = tb_v7908; }
    { const char * tb_v7909 = "    if (tb_vmm) { tb_vmm_read(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7909; }
    { const char * tb_v7910 = "    if (tb_mpn == 0 && !(b & 8)) return;           // первый байт пакета всегда с битом 3\n"; *(const char * *)tb_grow(v_lines) = tb_v7910; }
