    { const char * tb_v8998 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8998; }
    { const char * tb_v8999 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v8999; }
