    { const char * tb_v9010 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v9010; }
    { const char * tb_v9011 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v9011; }
    { const char * tb_v9012 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v9012; }
    { const char * tb_v9013 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v9013; }
    { const char * tb_v9014 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v9014; }
    { const char * tb_v9015 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v9015; }
    { const char * tb_v9016 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9016; }
    { const char * tb_v9017 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9017; }
    { const char * tb_v9018 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9018; }
    { const char * tb_v9019 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9019; }
    { const char * tb_v9020 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9020; }
    { const char * tb_v9021 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v9021; }
    { const char * tb_v9022 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9022; }
    { const char * tb_v9023 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v9023; }
    { const char * tb_v9024 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v9024; }
    { const char * tb_v9025 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v9025; }
    { const char * tb_v9026 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9026; }
    { const char * tb_v9027 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9027; }
    { const char * tb_v9028 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v9028; }
    { const char * tb_v9029 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v9029; }
    { const char * tb_v9030 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v9030; }
    { const char * tb_v9031 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9031; }
    { const char * tb_v9032 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9032; }
    { const char * tb_v9033 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9033; }
    { const char * tb_v9034 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9034; }
    { const char * tb_v9035 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9035; }
    { const char * tb_v9036 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
    { const char * tb_v9037 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9037; }
    { const char * tb_v9038 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9038; }
    { const char * tb_v9039 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v9039; }
    { const char * tb_v9040 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9040; }
    { const char * tb_v9041 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9041; }
    { const char * tb_v9042 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9042; }
    { const char * tb_v9043 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9043; }
    { const char * tb_v9044 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9044; }
    { const char * tb_v9045 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9045; }
    { const char * tb_v9046 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9046; }
    { const char * tb_v9047 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9047; }
    { const char * tb_v9048 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9048; }
    { const char * tb_v9049 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9049; }
    { const char * tb_v9050 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9050; }
    { const char * tb_v9051 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9051; }
    { const char * tb_v9052 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9052; }
    { const char * tb_v9053 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v9053; }
    { const char * tb_v9054 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9054; }
    { const char * tb_v9055 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9055; }
    { const char * tb_v9056 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v9056; }
    { const char * tb_v9057 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9057; }
    { const char * tb_v9058 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9058; }
    { const char * tb_v9059 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9059; }
    { const char * tb_v9060 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9060; }
    { const char * tb_v9061 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v9061; }
    { const char * tb_v9062 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9062; }
    { const char * tb_v9063 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9063; }
    { const char * tb_v9064 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9064; }
    { const char * tb_v9065 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9065; }
    { const char * tb_v9066 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v9066; }
    { const char * tb_v9067 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v9067; }
    { const char * tb_v9068 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v9068; }
    { const char * tb_v9069 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9069; }
    { const char * tb_v9070 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9070; }
    { const char * tb_v9071 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9071; }
    { const char * tb_v9072 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9072; }
    { const char * tb_v9073 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9073; }
    { const char * tb_v9074 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9074; }
    { const char * tb_v9075 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v9075; }
    { const char * tb_v9076 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9076; }
    { const char * tb_v9077 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v9077; }
    { const char * tb_v9078 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9078; }
    { const char * tb_v9079 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9079; }
    { const char * tb_v9080 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v9080; }
    { const char * tb_v9081 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9081; }
    { const char * tb_v9082 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9082; }
    { const char * tb_v9083 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9083; }
    { const char * tb_v9084 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9084; }
    { const char * tb_v9085 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9085; }
    { const char * tb_v9086 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v9086; }
    { const char * tb_v9087 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9087; }
    { const char * tb_v9088 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v9088; }
    { const char * tb_v9089 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v9089; }
    { const char * tb_v9090 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9090; }
    { const char * tb_v9091 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9091; }
