    { const char * tb_v9171 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9171; }
    { const char * tb_v9172 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9172; }
    { const char * tb_v9173 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9173; }
