    { const char * tb_v9176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9176; }
    { const char * tb_v9177 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v9177; }
    { const char * tb_v9178 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9178; }
    { const char * tb_v9179 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9179; }
    { const char * tb_v9180 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9180; }
    { const char * tb_v9181 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9181; }
