    { const char * tb_v9219 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
    { const char * tb_v9223 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9223; }
    { const char * tb_v9224 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9224; }
    { const char * tb_v9225 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9225; }
    { const char * tb_v9226 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9226; }
