    { const char * tb_v9232 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
    { const char * tb_v9233 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v9233; }
    { const char * tb_v9234 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9234; }
    { const char * tb_v9235 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9235; }
    { const char * tb_v9236 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v9236; }
    { const char * tb_v9237 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9237; }
    { const char * tb_v9238 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9238; }
    { const char * tb_v9239 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9239; }
    { const char * tb_v9240 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v9240; }
    { const char * tb_v9241 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9241; }
    { const char * tb_v9242 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9242; }
    { const char * tb_v9243 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9243; }
    { const char * tb_v9244 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9244; }
    { const char * tb_v9245 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9245; }
    { const char * tb_v9246 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9246; }
    { const char * tb_v9247 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9247; }
    { const char * tb_v9248 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9248; }
    { const char * tb_v9249 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9249; }
    { const char * tb_v9250 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9250; }
    { const char * tb_v9251 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v9251; }
    { const char * tb_v9252 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9252; }
    { const char * tb_v9253 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v9253; }
    { const char * tb_v9254 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
    { const char * tb_v9255 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9255; }
    { const char * tb_v9256 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v9256; }
    { const char * tb_v9257 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9257; }
    { const char * tb_v9258 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9258; }
    { const char * tb_v9259 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v9259; }
    { const char * tb_v9260 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9260; }
    { const char * tb_v9261 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9261; }
    { const char * tb_v9262 = "            double cx = side ? x + w - r - 0.5 : x + r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9262; }
    { const char * tb_v9263 = "            long long i0 = side ? x + w - r : x, i1 = side ? x + w : x + r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9263; }
    { const char * tb_v9264 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9264; }
    { const char * tb_v9265 = "                double dx = i + 0.5 - (cx + 0.5), dy = j + 0.5 - (cy + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9265; }
    { const char * tb_v9266 = "                double d = sqrt(dx * dx + dy * dy);\n"; *(const char * *)tb_grow(v_lines) = tb_v9266; }
