    { const char * tb_v9270 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9270; }
    { const char * tb_v9271 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9271; }
    { const char * tb_v9272 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v9272; }
    { const char * tb_v9273 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9273; }
    { const char * tb_v9274 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9274; }
    { const char * tb_v9275 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v9275; }
    { const char * tb_v9276 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9276; }
    { const char * tb_v9277 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v9277; }
    { const char * tb_v9278 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9278; }
    { const char * tb_v9279 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9279; }
    { const char * tb_v9280 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9280; }
    { const char * tb_v9281 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9281; }
    { const char * tb_v9282 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9282; }
    { const char * tb_v9283 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v9283; }
    { const char * tb_v9284 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v9284; }
    { const char * tb_v9285 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9285; }
    { const char * tb_v9286 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9286; }
    { const char * tb_v9287 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9287; }
    { const char * tb_v9288 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
    { const char * tb_v9291 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v9291; }
    { const char * tb_v9292 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v9292; }
    { const char * tb_v9293 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9293; }
    { const char * tb_v9294 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9294; }
    { const char * tb_v9295 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9295; }
    { const char * tb_v9296 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9296; }
    { const char * tb_v9297 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9297; }
    { const char * tb_v9298 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9298; }
    { const char * tb_v9299 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9299; }
    { const char * tb_v9300 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9300; }
    { const char * tb_v9301 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9301; }
    { const char * tb_v9302 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9302; }
    { const char * tb_v9303 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9303; }
    { const char * tb_v9304 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9304; }
    { const char * tb_v9305 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9305; }
    { const char * tb_v9306 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9306; }
    { const char * tb_v9307 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9307; }
    { const char * tb_v9308 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v9308; }
    { const char * tb_v9309 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v9309; }
    { const char * tb_v9310 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9310; }
    { const char * tb_v9311 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9311; }
    { const char * tb_v9312 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9312; }
    { const char * tb_v9313 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9313; }
    { const char * tb_v9314 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9314; }
    { const char * tb_v9315 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9315; }
    { const char * tb_v9316 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9316; }
    { const char * tb_v9317 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9317; }
    { const char * tb_v9318 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9318; }
    { const char * tb_v9319 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9319; }
    { const char * tb_v9320 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9320; }
    { const char * tb_v9321 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9321; }
    { const char * tb_v9322 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9322; }
    { const char * tb_v9323 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9323; }
    { const char * tb_v9324 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9324; }
    { const char * tb_v9325 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v9325; }
    { const char * tb_v9326 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9326; }
    { const char * tb_v9327 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9327; }
    { const char * tb_v9328 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9328; }
    { const char * tb_v9329 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9329; }
    { const char * tb_v9330 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9330; }
    { const char * tb_v9331 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v9331; }
    { const char * tb_v9332 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9332; }
    { const char * tb_v9333 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9333; }
    { const char * tb_v9334 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9334; }
    { const char * tb_v9335 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9335; }
    { const char * tb_v9336 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9336; }
    { const char * tb_v9337 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9337; }
    { const char * tb_v9338 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9338; }
    { const char * tb_v9339 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9339; }
    { const char * tb_v9340 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9340; }
    { const char * tb_v9341 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9341; }
    { const char * tb_v9342 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9342; }
    { const char * tb_v9343 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9343; }
    { const char * tb_v9344 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9344; }
    { const char * tb_v9345 = "            if (i * i + j * j <= r * r + r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9345; }
    { const char * tb_v9346 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9346; }
