    { const char * tb_v9553 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
    { const char * tb_v9554 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9554; }
