    { const char * tb_v9789 = "static void tb_tex_rec_i(const tb_mesh *m, long long t, const long long *a, const long long *b, const long long *c, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9789; }
