    { const char * tb_v9834 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double R[3][3], const int32_t *L, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9834; }
