    { const char * tb_v9901 = "            if (p->front) { qx[n] = p->cx; qy[n] = p->cy; qz[n] = p->cz; if (uv) { qu[n] = uv[2 * i]; qv[n] = uv[2 * i + 1]; } n++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9901; }
