    { const char * tb_v9939 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9939; }
    { const char * tb_v9940 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9940; }
    { const char * tb_v9941 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v9941; }
    { const char * tb_v9942 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v9942; }
    { const char * tb_v9943 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9943; }
    { const char * tb_v9944 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9944; }
    { const char * tb_v9945 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9945; }
    { const char * tb_v9946 = "    int ret = area > 0 ? 1 : 2;   // 1 — грань смотрит на нас, 2 — спиной\n"; *(const char * *)tb_grow(v_lines) = tb_v9946; }
    { const char * tb_v9947 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9947; }
    { const char * tb_v9948 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9948; }
    { const char * tb_v9949 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9949; }
    { const char * tb_v9950 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9950; }
    { const char * tb_v9951 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v9951; }
    { const char * tb_v9952 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9952; }
    { const char * tb_v9953 = "    return ret;\n"; *(const char * *)tb_grow(v_lines) = tb_v9953; }
    { const char * tb_v9954 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9954; }
    { const char * tb_v9955 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9955; }
    { const char * tb_v9956 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9956; }
    { const char * tb_v9957 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9957; }
    { const char * tb_v9958 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9958; }
    { const char * tb_v9959 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9959; }
    { const char * tb_v9960 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9960; }
    { const char * tb_v9961 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9961; }
    { const char * tb_v9962 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9962; }
    { const char * tb_v9963 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9963; }
    { const char * tb_v9964 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9964; }
    { const char * tb_v9965 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9965; }
    { const char * tb_v9966 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9966; }
    { const char * tb_v9967 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9967; }
    { const char * tb_v9968 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9968; }
    { const char * tb_v9969 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9969; }
    { const char * tb_v9970 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9970; }
    { const char * tb_v9971 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9971; }
    { const char * tb_v9972 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9972; }
    { const char * tb_v9973 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9973; }
    { const char * tb_v9974 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9974; }
    { const char * tb_v9975 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9975; }
    { const char * tb_v9976 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9976; }
    { const char * tb_v9977 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v9977; }
    { const char * tb_v9978 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v9978; }
    { const char * tb_v9979 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9979; }
    { const char * tb_v9980 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9980; }
    { const char * tb_v9981 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v9981; }
    { const char * tb_v9982 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9982; }
    { const char * tb_v9983 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9983; }
    { const char * tb_v9984 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9984; }
    { const char * tb_v9985 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v9985; }
    { const char * tb_v9986 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v9986; }
    { const char * tb_v9987 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9987; }
