    { const char * tb_v10246 = "    char *got = tb_gfx_clip_get();   // malloc или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v10246; }
    { const char * tb_v10247 = "    size_t n = got ? strlen(got) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10247; }
    { const char * tb_v10248 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10248; }
    { const char * tb_v10249 = "    if (n) memcpy(s, got, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v10249; }
    { const char * tb_v10250 = "    s[n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10250; }
    { const char * tb_v10251 = "    free(got);\n"; *(const char * *)tb_grow(v_lines) = tb_v10251; }
    { const char * tb_v10252 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v10252; }
    { const char * tb_v10253 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10253; }
    { const char * tb_v10254 = "TB_API void tb_clipboard_set(const char *s) { tb_gfx_clip_set(s ? s : \"\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10254; }
    { const char * tb_v10255 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v10255; }
    { const char * tb_v10256 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10256; }
    { const char * tb_v10257 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v10257; }
    { const char * tb_v10258 = "    for (int i = 0; i < 8; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v10258; }
    { const char * tb_v10259 = "        if (strcmp(name, names[i]) == 0) { if (tb_px) tb_gfx_cursor(i); else tb_cursor_want = i; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10259; }
    { const char * tb_v10260 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v10260; }
    { const char * tb_v10261 = "    snprintf(buf, sizeof buf, \"set_cursor: нет курсора «%s»; есть arrow, hand, text, move, resize_x, resize_y, wait, none\", name);\n"; *(const char * *)tb_grow(v_lines) = tb_v10261; }
    { const char * tb_v10262 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v10262; }
    { const char * tb_v10263 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10263; }
    { const char * tb_v10264 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10264; }
    { const char * tb_v10265 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10265; }
    { const char * tb_v10266 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v10266; }
    { const char * tb_v10267 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v10267; }
    { const char * tb_v10268 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v10268; }
    { const char * tb_v10269 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v10269; }
    { const char * tb_v10270 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10270; }
    { const char * tb_v10271 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v10271; }
    { const char * tb_v10272 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v10272; }
    { const char * tb_v10273 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v10273; }
    { const char * tb_v10274 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v10274; }
    { const char * tb_v10275 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v10275; }
    { const char * tb_v10276 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v10276; }
    { const char * tb_v10277 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v10277; }
    { const char * tb_v10278 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v10278; }
    { const char * tb_v10279 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v10279; }
    { const char * tb_v10280 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v10280; }
    { const char * tb_v10281 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v10281; }
    { const char * tb_v10282 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10282; }
    { const char * tb_v10283 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v10283; }
    { const char * tb_v10284 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v10284; }
    { const char * tb_v10285 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v10285; }
    { const char * tb_v10286 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10286; }
    { const char * tb_v10287 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10287; }
    { const char * tb_v10288 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10288; }
    { const char * tb_v10289 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v10289; }
    { const char * tb_v10290 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v10290; }
    { const char * tb_v10291 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v10291; }
    { const char * tb_v10292 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v10292; }
    { const char * tb_v10293 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v10293; }
    { const char * tb_v10294 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v10294; }
    { const char * tb_v10295 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v10295; }
    { const char * tb_v10296 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v10296; }
    { const char * tb_v10297 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v10297; }
    { const char * tb_v10298 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10298; }
    { const char * tb_v10299 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10299; }
    { const char * tb_v10300 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10300; }
    { const char * tb_v10301 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v10301; }
    { const char * tb_v10302 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v10302; }
    { const char * tb_v10303 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10303; }
    { const char * tb_v10304 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10304; }
    { const char * tb_v10305 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10305; }
    { const char * tb_v10306 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10306; }
    { const char * tb_v10307 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10307; }
    { const char * tb_v10308 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10308; }
    { const char * tb_v10309 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v10309; }
    { const char * tb_v10310 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10310; }
    { const char * tb_v10311 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v10311; }
    { const char * tb_v10312 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10312; }
    { const char * tb_v10313 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v10313; }
    { const char * tb_v10314 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v10314; }
    { const char * tb_v10315 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v10315; }
    { const char * tb_v10316 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10316; }
    { const char * tb_v10317 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v10317; }
    { const char * tb_v10318 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10318; }
    { const char * tb_v10319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10319; }
    { const char * tb_v10320 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10320; }
    { const char * tb_v10321 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v10321; }
    { const char * tb_v10322 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v10322; }
    { const char * tb_v10323 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10323; }
    { const char * tb_v10324 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v10324; }
    { const char * tb_v10325 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10325; }
    { const char * tb_v10326 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10326; }
    { const char * tb_v10327 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v10327; }
    { const char * tb_v10328 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10328; }
    { const char * tb_v10329 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10329; }
    { const char * tb_v10330 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v10330; }
    { const char * tb_v10331 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10331; }
    { const char * tb_v10332 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10332; }
    { const char * tb_v10333 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v10333; }
    { const char * tb_v10334 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10334; }
    { const char * tb_v10335 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10335; }
    { const char * tb_v10336 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10336; }
    { const char * tb_v10337 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10337; }
    { const char * tb_v10338 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10338; }
    { const char * tb_v10339 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v10339; }
    { const char * tb_v10340 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v10340; }
    { const char * tb_v10341 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v10341; }
    { const char * tb_v10342 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10342; }
    { const char * tb_v10343 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v10343; }
    { const char * tb_v10344 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v10344; }
    { const char * tb_v10345 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10345; }
    { const char * tb_v10346 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10346; }
    { const char * tb_v10347 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10347; }
    { const char * tb_v10348 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v10348; }
    { const char * tb_v10349 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v10349; }
    { const char * tb_v10350 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v10350; }
    { const char * tb_v10351 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10351; }
    { const char * tb_v10352 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10352; }
    { const char * tb_v10353 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v10353; }
    { const char * tb_v10354 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10354; }
    { const char * tb_v10355 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10355; }
    { const char * tb_v10356 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v10356; }
    { const char * tb_v10357 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v10357; }
    { const char * tb_v10358 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v10358; }
    { const char * tb_v10359 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10359; }
    { const char * tb_v10360 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10360; }
    { const char * tb_v10361 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10361; }
    { const char * tb_v10362 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10362; }
    { const char * tb_v10363 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10363; }
    { const char * tb_v10364 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v10364; }
    { const char * tb_v10365 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10365; }
    { const char * tb_v10366 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v10366; }
    { const char * tb_v10367 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v10367; }
    { const char * tb_v10368 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10368; }
    { const char * tb_v10369 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v10369; }
    { const char * tb_v10370 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10370; }
    { const char * tb_v10371 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v10371; }
    { const char * tb_v10372 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10372; }
    { const char * tb_v10373 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10373; }
    { const char * tb_v10374 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10374; }
    { const char * tb_v10375 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v10375; }
    { const char * tb_v10376 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10376; }
    { const char * tb_v10377 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10377; }
    { const char * tb_v10378 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10378; }
    { const char * tb_v10379 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10379; }
    { const char * tb_v10380 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10380; }
